  const ipUsed = quotaCount(day?.ips?.[context.ipKey]);
  const systemUsed = quotaCount(day?.used);
  return { ipLimit: IP_LIMIT, ipUsed, ipRemaining: Math.max(0, IP_LIMIT - ipUsed),
